WITH valid AS (SELECT id, product_name, brand, price, cost, stock_qty, launch_date, ROUND(stock_qty / price, 2) AS stock_qty_per_price, COALESCE(brand, 'DIRECT') AS brand_clean FROM products WHERE launch_date > DATE '2023-07-23' AND supplier_id IS NOT NULL), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY brand ORDER BY price DESC NULLS FIRST, id ASC) AS latest_rank FROM valid) t WHERE latest_rank = 1), not_flagged AS (SELECT s.* FROM ranked s WHERE EXISTS (SELECT 1 FROM order_items x WHERE x.product_id = s.id AND x.product_id = 13)), enriched AS (SELECT *, SUM(stock_qty) OVER (PARTITION BY brand ORDER BY latest_rank ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_stock_qty, LAG(stock_qty, 1) OVER (PARTITION BY brand ORDER BY cost ASC, id ASC) AS prev_stock_qty, ROUND(cost / SUM(cost) OVER (PARTITION BY brand), 4) AS cost_share FROM not_flagged) SELECT *, STDDEV_SAMP(cost) OVER (PARTITION BY brand) AS brand_stddev_samp_cost, COUNT(price) OVER (PARTITION BY brand) AS brand_count_price FROM enriched
